-- Somente leitura. Executar como postgres após 011. Zero linhas = sem divergências destas verificações.
WITH scoped AS (
 SELECT c.oid,n.nspname,c.relname,c.relrowsecurity,c.relowner FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE c.relkind='r' AND (n.nspname IN ('iasdpi_admin_private','iasdpi_operational_private','iasdpi_schedule_private')
 OR (n.nspname='public' AND (c.relname IN ('iasdpi_access','iasdpi_templates','culto_archives','iasdpi_programs','iasdpi_activities','iasdpi_subactivities') OR c.relname LIKE 'schedule\_%' ESCAPE '\')))
), issues AS (
 SELECT 'church_registry' issue,'IASD_PI deve existir ativa e listada' detail WHERE NOT EXISTS(SELECT 1 FROM public.iasdpi_churches WHERE code='IASD_PI' AND active AND listed)
 UNION ALL SELECT 'church_control',c.code FROM public.iasdpi_churches c WHERE NOT EXISTS(SELECT 1 FROM iasdpi_admin_private.control x WHERE x.church_id=c.id AND x.singleton)
 UNION ALL SELECT 'table_owner',s.nspname||'.'||s.relname FROM scoped s WHERE s.relowner<>'postgres'::regrole
 UNION ALL SELECT 'rls',s.nspname||'.'||s.relname FROM scoped s WHERE NOT s.relrowsecurity
 UNION ALL SELECT 'scope_column',s.nspname||'.'||s.relname FROM scoped s WHERE NOT EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=s.oid AND a.attname='church_id' AND a.attnotnull AND NOT a.attisdropped)
 UNION ALL SELECT 'scope_policy',s.nspname||'.'||s.relname FROM scoped s WHERE NOT EXISTS(SELECT 1 FROM pg_policy p WHERE p.polrelid=s.oid AND p.polname='church_boundary' AND NOT p.polpermissive AND pg_get_expr(p.polqual,p.polrelid) LIKE '%iasdpi_current_church_id%')
 UNION ALL SELECT 'function_owner',p.oid::regprocedure::text FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE (n.nspname IN ('iasdpi_admin_private','iasdpi_operational_private','iasdpi_schedule_private') OR (n.nspname='public' AND p.proname LIKE 'iasdpi\_%' ESCAPE '\' AND p.proname NOT IN ('iasdpi_list_churches','iasdpi_current_church_id','iasdpi_my_churches'))) AND p.proowner<>'iasdpi_church_executor'::regrole
 UNION ALL SELECT 'context_bridge_owner',p.oid::regprocedure::text FROM pg_proc p WHERE p.oid=to_regprocedure('public.iasdpi_my_churches()') AND p.proowner<>'postgres'::regrole
 UNION ALL SELECT 'private_execute',p.oid::regprocedure::text FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('iasdpi_admin_private','iasdpi_operational_private','iasdpi_schedule_private') AND (has_function_privilege('authenticated',p.oid,'EXECUTE') OR has_function_privilege('anon',p.oid,'EXECUTE'))
 UNION ALL SELECT 'executor_role',r.rolname FROM pg_roles r WHERE r.rolname='iasdpi_church_executor' AND (r.rolsuper OR r.rolbypassrls OR r.rolcanlogin OR r.rolcreatedb OR r.rolcreaterole OR r.rolinherit)
 UNION ALL SELECT 'executor_membership',m.member::regrole::text FROM pg_auth_members m WHERE (m.roleid='iasdpi_church_executor'::regrole AND m.member<>'postgres'::regrole) OR m.member='iasdpi_church_executor'::regrole
 UNION ALL SELECT 'executor_create',n.nspname FROM pg_namespace n WHERE n.nspname IN ('public','iasdpi_admin_private','iasdpi_operational_private','iasdpi_schedule_private') AND has_schema_privilege('iasdpi_church_executor',n.oid,'CREATE')
 UNION ALL SELECT 'private_schema',n.nspname FROM pg_namespace n WHERE n.nspname IN ('iasdpi_admin_private','iasdpi_operational_private','iasdpi_schedule_private') AND (has_schema_privilege('authenticated',n.oid,'USAGE') OR has_schema_privilege('anon',n.oid,'USAGE'))
 UNION ALL SELECT 'definer_search_path',p.oid::regprocedure::text FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prosecdef AND (n.nspname IN ('iasdpi_admin_private','iasdpi_operational_private','iasdpi_schedule_private') OR (n.nspname='public' AND p.proname LIKE 'iasdpi\_%' ESCAPE '\')) AND NOT coalesce('search_path=""'=ANY(p.proconfig),false)
 UNION ALL SELECT 'cross_scope_fk',f.conname FROM pg_constraint f JOIN scoped child ON child.oid=f.conrelid JOIN scoped parent ON parent.oid=f.confrelid WHERE f.contype='f' AND NOT EXISTS(SELECT 1 FROM pg_constraint boundary WHERE boundary.contype='f' AND boundary.conrelid=f.conrelid AND boundary.confrelid=f.confrelid AND boundary.conkey @> f.conkey AND boundary.confkey @> f.confkey AND (SELECT a.attnum FROM pg_attribute a WHERE a.attrelid=f.conrelid AND a.attname='church_id')=ANY(boundary.conkey) AND (SELECT a.attnum FROM pg_attribute a WHERE a.attrelid=f.confrelid AND a.attname='church_id')=ANY(boundary.confkey))
 UNION ALL SELECT 'auth_bridge','Ponte Auth ausente, exposta ou proprietário incorreto' WHERE NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=to_regclass('iasdpi_admin_private.auth_accounts') AND c.relowner='postgres'::regrole AND c.relkind='v') OR has_table_privilege('authenticated','iasdpi_admin_private.auth_accounts','SELECT') OR has_table_privilege('anon','iasdpi_admin_private.auth_accounts','SELECT')
 UNION ALL SELECT 'view_owner',c.oid::regclass::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='iasdpi_schedule_private' AND c.relkind='v' AND (c.relowner<>'iasdpi_church_executor'::regrole OR NOT coalesce(c.reloptions @> ARRAY['security_invoker=true'],false))
)
SELECT issue,detail FROM issues ORDER BY issue,detail;
